// The board as the rules need it (decide.ts): every card that is not done,
// with its text and its thread, and its pull request where the builder
// opened one. Cards that are done, or in the backlog, need no more reading.
import { branchOf } from "./branches.js";
const READ = [
    "planning",
    "todo",
    "doing",
    "review",
];
export async function snapshotOf(listed, cards, pullRequests) {
    const read = [];
    for (const card of listed)
        read.push(await boardCard(card, cards, pullRequests));
    return read;
}
async function boardCard(card, cards, pullRequests) {
    const plain = {
        number: card.number,
        title: card.title,
        url: card.url,
        body: "",
        stage: card.stage,
        closed: card.closed,
        agreedInText: false,
        waitsFor: card.waitsFor,
        thread: [],
        pullRequest: null,
    };
    if (card.closed || !READ.includes(card.stage))
        return plain;
    const detail = await cards.show(card.number);
    const found = card.stage === "doing" || card.stage === "review"
        ? await pullRequests.find(branchOf(card.number))
        : null;
    return {
        ...plain,
        body: detail.body,
        agreedInText: detail.agreed,
        thread: detail.comments.map((c) => ({ ...c, where: "card" })),
        pullRequest: found && {
            ...found,
            thread: found.state === "OPEN" ? await pullRequests.said(found.number) : [],
        },
    };
}
